// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 ts) public {
        ts = bound(ts, 2, type(uint256).max - 1);
        vm.warp(ts - 1);
        // first call at ts: accepted by both versions (ts - 1 < ts)
        vm.warp(ts);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call at a strictly later timestamp must succeed");
        // a second call at the SAME timestamp ts: the reference rejects it,
        // because a successful call only advances the accepted timestamp strictly.
        vm.deal(address(this), 10 ether);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2, "a duplicate call at the same timestamp must be rejected");
    }
}
